module A {
  type T1 = | A(int)
}

module B {
  type T2 = | A(bool)
}

module wrapper { type T = A(int) | B
val a = variant("A", 3)
val nine = match a { A(n) => n * n | B => 9 } }

module wrapper { type T = A(int) | B
val a = variant("A", 3)
