module wrapper { type T = A(int) | B | C
val a = variant("A", 3)
val nine = match B { A(n) => "OK" | _ => "first wildcard" | _ => "second, invalid wildcard" } }

module wrapper { type T = A(int) | B | C
val a = variant("A", 3)
val nine = match B { A(n) => "OK" | _ => "invalid, non-final wildcard" | C => "OK" } }

module wrapper { type T = A(int) | B
val a = variant("A", 3)
val nine = matchVariant(a, 3, (_ => 9)) }

